import java.util.*;
import java.util.stream.*;

public class ScanSymulacja {
    record Wynik(int kursor, List<String> klucze) {}
    static List<String> wszystkie = new ArrayList<>();

    static Wynik scan(int kursor, String wzorzec, int count) {
        String regex = wzorzec.replace("*", ".*");
        int koniec = Math.min(kursor + count, wszystkie.size());
        List<String> pasujace = wszystkie.subList(kursor, koniec).stream()
            .filter(k -> k.matches(regex)).toList();
        return new Wynik(koniec >= wszystkie.size() ? 0 : koniec, pasujace);
    }

    public static void main(String[] args) {
        for (int i = 0; i < 25; i++) { wszystkie.add("user:" + i); wszystkie.add("produkt:" + i); }
        List<String> zebrane = new ArrayList<>();
        int kursor = 0, kroki = 0;
        do {
            Wynik w = scan(kursor, "user:*", 10);
            zebrane.addAll(w.klucze());
            kursor = w.kursor();
            kroki++;
        } while (kursor != 0);
        System.out.println("kroki=" + kroki + " znaleziono=" + zebrane.size()); // kroki=5 znaleziono=25
    }
}
Każdy krok zwraca ok. 5 pasujących kluczy, choć COUNT=10 - dokładnie jak w Redis, gdzie MATCH filtruje przejrzaną porcję.

